import { mkdir, writeFile } from "node:fs/promises";
import { createHash } from "node:crypto";
import { resolve } from "node:path";
import { captureModernLocalSchema, createProductionClone } from "../../../../supabase/rls-tests/helpers/productionSchemaClone";
import { captureGuardRawState, assertGuardRawPreserved, rawStateDigests, type RawCloneState } from "../../../../supabase/rls-tests/helpers/documentGuardPreservation";
const out=resolve(import.meta.dir,"observer-"+new Date().toISOString().replaceAll(/[^0-9T]/g,""));
await mkdir(out);
const sha=(v:string)=>createHash("sha256").update(v).digest("hex");
let clone:Awaited<ReturnType<typeof createProductionClone>>|undefined;
const observations:unknown[]=[];
const receipt:Record<string,unknown>={scope:"One fresh zero-data loopback clone; repeated read-only observations only after setup; no migration, fixtures, role/engine changes, provider or production operations",startedAt:new Date().toISOString(),output:out,normalDrop:false};
async function observe(){
 if(!clone)throw new Error("No owned clone");
 return clone.sql.begin(async tx=>{
  await tx`set transaction isolation level repeatable read read only`;
  await tx`set local statement_timeout='30s'`;
  const context=await tx`select clock_timestamp()::text as at,pg_backend_pid()::text as backend,current_database() as database,current_user as actor,current_setting('server_version_num') as version,current_setting('autovacuum') as autovacuum,current_setting('log_autovacuum_min_duration') as log_autovacuum_min_duration`;
  const tables=await tx`select s.relid::text as oid,s.relname,c.relpages::text,c.reltuples::text,c.relallvisible::text,c.relfrozenxid::text,s.last_analyze::text,s.last_autoanalyze::text,s.analyze_count::text,s.autoanalyze_count::text from pg_catalog.pg_stat_all_tables s join pg_catalog.pg_class c on c.oid=s.relid where s.schemaname='pg_catalog' order by s.relid`;
  const workers=await tx`select pid::text,backend_type,state from pg_catalog.pg_stat_activity where datname=current_database() and backend_type='autovacuum worker' order by pid`;
  return {context,tables,workers};
 });
}
try{
 const captured=await captureModernLocalSchema();
 clone=await createProductionClone(captured);
 receipt.clone=clone.name;receipt.zeroDataTables=clone.tableCount;
 observations.push(await observe());
 const before=await captureGuardRawState(clone.sql,clone.url);
 receipt.before=rawStateDigests(before);
 await writeFile(resolve(out,"before-statistics.json"),JSON.stringify(before.catalogs["pg_catalog.pg_statistic"]));
 for(let i=0;i<8;i++){
  await Bun.sleep(5000);
  observations.push(await observe());
  console.log(JSON.stringify({phase:"READ_ONLY_OBSERVER",sample:i+1,clone:clone.name}));
 }
 const after=await captureGuardRawState(clone.sql,clone.url);
 observations.push(await observe());receipt.after=rawStateDigests(after);
 await writeFile(resolve(out,"after-statistics.json"),JSON.stringify(after.catalogs["pg_catalog.pg_statistic"]));
 const statMap=(v:RawCloneState)=>new Map(v.catalogs["pg_catalog.pg_statistic"].map(r=>{const p=JSON.parse(r.raw) as {starelid:string;staattnum:number;stainherit:boolean};return [p.starelid+"/"+p.staattnum+"/"+p.stainherit,r.raw] as const;}));
 const a=statMap(before),b=statMap(after);
 receipt.statisticChanges={beforeIdentities:a.size,afterIdentities:b.size,removedIdentities:[...a.keys()].filter(k=>!b.has(k)),addedIdentities:[...b.keys()].filter(k=>!a.has(k)),changedIdentities:[...a].filter(([k,v])=>b.has(k)&&b.get(k)!==v).map(([k])=>k),sameInventory:before.inventory===after.inventory};
 try{receipt.strictReadOnlyObserverPreservation=assertGuardRawPreserved(before,after,[],new Set<string>(),new Set<string>());}
 catch(error){receipt.strictReadOnlyObserverError={message:error instanceof Error?error.message:String(error),code:error!==null&&typeof error==="object"&&"code" in error?String(error.code):null};}
 await writeFile(resolve(out,"before-digests.json"),JSON.stringify(rawStateDigests(before)));
 await writeFile(resolve(out,"after-digests.json"),JSON.stringify(rawStateDigests(after)));
}catch(error){
 receipt.setupOrReadError={message:error instanceof Error?error.message:String(error),code:error!==null&&typeof error==="object"&&"code" in error?String(error.code):null};process.exitCode=1;
}finally{
 try{if(clone){await clone.close();receipt.normalDrop=true;receipt.templatePreserved=clone.templatePreserved;}}
 catch(error){receipt.cleanupError=error instanceof Error?error.message:String(error);process.exitCode=1;}
 receipt.endedAt=new Date().toISOString();
 await writeFile(resolve(out,"observations.json"),JSON.stringify(observations,null,2));
 await writeFile(resolve(out,"receipt.json"),JSON.stringify(receipt,null,2));
 console.log(JSON.stringify({output:out,setupOrReadError:receipt.setupOrReadError??null,normalDrop:receipt.normalDrop,templatePreserved:receipt.templatePreserved??null,zeroDataTables:receipt.zeroDataTables??null,statisticChanges:receipt.statisticChanges??null,strictReadOnlyObserverError:receipt.strictReadOnlyObserverError??null,qualification:"Diagnostic only; not a restored-migration preservation pass or failure waiver"}));
}

